INSERT INTO teacher_rules_relay_state (relay_id, student, rounds_done, finished, confirmed, updated_at) SELECT r.id, :student, 1, CASE WHEN r.rounds <= 1 THEN 1 ELSE 0 END, 0, datetime('now', 'localtime') FROM teacher_rules_relay r WHERE instr(',' || replace(:ids, ' ', '') || ',', ',' || r.id || ',') > 0 AND NOT EXISTS (SELECT 1 FROM teacher_rules_relay_state s WHERE s.relay_id = r.id AND s.student = :student)
